import{_ as o,a as t,c as a,b as r}from"./chunks/framework.b9WMfGr4.js";const h=JSON.parse('{"title":"03-排版风格与标点规范","description":"规范技术博客的排版习惯、标点符号准则、中英文混排规则与模拟小标题排版协同。","frontmatter":{"title":"03-排版风格与标点规范","date":"2026-10-01T00:00:00.000Z","author":"道林学长","description":"规范技术博客的排版习惯、标点符号准则、中英文混排规则与模拟小标题排版协同。","tags":["写作规范","排版规范"]},"headers":[],"relativePath":"posts/0-博客指南/博客的写作规范/03-排版风格与标点规范.md","filePath":"posts/0-博客指南/博客的写作规范/03-排版风格与标点规范.md"}'),s={name:"posts/0-博客指南/博客的写作规范/03-排版风格与标点规范.md"};function i(l,e,n,c,d,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 class="hidden-duplicate-h1" style="display:none !important;" id="_03-排版风格与标点规范" tabindex="-1">03-排版风格与标点规范 <a class="header-anchor" href="#_03-排版风格与标点规范" aria-label="Permalink to &quot;03-排版风格与标点规范&quot;">​</a></h1><div class="post-cover-wrapper"><img src="https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?auto=format&amp;fit=crop&amp;w=1200&amp;q=80" alt="cover" class="post-cover-image" referrerpolicy="no-referrer" loading="lazy"></div><p>文字排版直接决定了读者的阅读呼吸感与思维节奏。在严谨的技术写作中，规范的标点符号使用与清爽的段落编排，能够有效传递专业度并降低阅读障碍。</p><h2 id="_1-坚决不使用中文全角括号补充说明" tabindex="-1">1. 坚决不使用中文全角括号补充说明 <a class="header-anchor" href="#_1-坚决不使用中文全角括号补充说明" aria-label="Permalink to &quot;1. 坚决不使用中文全角括号补充说明&quot;">​</a></h2><p>在技术写作习惯中，博主坚决不使用中文全角括号来进行内容补充、背景修饰或夹注说明。</p><p>中文全角括号极易割裂句式主干，诱使作者将重要论据碎片化地塞入括号内，从而破坏逻辑叙述的流畅感与严密性。在日常撰写中，应遵循以下重构准则：</p><ul><li><strong>融入正文自然表达</strong>：将修饰、背景解释或定义说明直接作为句子主干的一部分，用逗号连接并自然道出。</li><li><strong>使用破折号强化转折</strong>：需要插入递进或补充时，采用破折号进行语义延伸，增强阅读节奏感。</li><li><strong>独立拆分为递进短句</strong>：若补充信息篇幅较长，直接另起一句完整论述，形成主谓宾完整的独立陈述。</li><li><strong>语法文档特例说明</strong>：语法说明文档 <code>posts/0-博客指南/博客的语法/02-文本行内样式.md</code> 作为全站特例，因需要专门举例分析并验证中文全角括号紧邻汉字导致的 CommonMark 定界符解析缺陷，允许保留测试用例，全站其余所有文章均须严格遵从杜绝中文括号的习惯。</li></ul><h2 id="_2-中英文与代码混排规范" tabindex="-1">2. 中英文与代码混排规范 <a class="header-anchor" href="#_2-中英文与代码混排规范" aria-label="Permalink to &quot;2. 中英文与代码混排规范&quot;">​</a></h2><p>技术文档充斥着英文缩写、类名、方法名以及行内代码。博客在编译期提供自动化排版引擎，但在书写源文档时也应保持规整习惯：</p><ul><li><strong>自动补充微间距</strong>：系统在渲染时会自动在汉字与英文字符、数字、行内代码之间注入微空格。作者撰写时无论是否手动键入空格，页面渲染均呈现优美间距。</li><li><strong>标点符号归属原则</strong>：中文正文段落中使用全角逗号、句号、冒号与分号；在代码片段、文件名后缀、版本号、网络协议中严格使用标准半角符号。</li><li><strong>专有名词大小写规范</strong>：技术专有名词严格遵循官方标准大小写，例如编写 <code>TypeScript</code> 而非 <code>typescript</code>，编写 <code>MySQL</code> 而非 <code>mysql</code>，编写 <code>VitePress</code> 而非 <code>vitepress</code>。</li></ul><h2 id="_3-模拟小标题排版协同" tabindex="-1">3. 模拟小标题排版协同 <a class="header-anchor" href="#_3-模拟小标题排版协同" aria-label="Permalink to &quot;3. 模拟小标题排版协同&quot;">​</a></h2><p>为了在控制大纲深度的前提下保持段落层次分明，博客引入了整行粗体模拟小标题机制：</p><ul><li><strong>语法识别形式</strong>：单独占据一个自然段、且整行内容被加粗标记包裹的文本，系统在 AST 解析期会自动为其注入 <code>pseudo-heading</code> 样式类。</li><li><strong>视觉呈现与字号对齐</strong>：模拟小标题字号统一对齐为 18px，行高保持 1.4，上方自带 16px 留白，下方提供 8px 间距，视觉效果与三级标题完全一致。</li><li><strong>右侧目录不侵入</strong>：模拟小标题不作为真正的 HTML 标题标签插入，因此不会污染右侧文档大纲目录树，既实现了段落层级拆分，又维持了大纲目录的高效聚焦。</li></ul>',13)])])}const g=o(s,[["render",i]]);export{h as __pageData,g as default};
